{
  "title": "迷雾中的巨灵",
  "scene": "玩家站在一片被浓雾笼罩的古老森林中，四周的树木高耸入云，枝叶繁茂。远处隐约传来巨灵的低吼声，空气中弥漫着一股古老而神秘的气息。玩家需要找到隐藏在迷雾中的巨灵，解开它身上的谜题，才能继续前行。",
  "goal": "找到巨灵并解开它的谜题，获取珍贵的山海经碎片。",
  "choices": [
    {
      "id": "A",
      "text": "跟随低吼声，穿过森林寻找巨灵。",
      "outcome": "玩家穿过森林，发现了一块石头上刻着古代文字，解读后得知巨灵被一种特殊的草药治愈，需要找到这种草药。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "尝试使用随身携带的山海经古籍，希望能够找到线索。",
      "outcome": "玩家翻开山海经古籍，其中一页突然发光，指引玩家前往一处隐蔽的洞穴，洞穴中有线索指向一种特殊的草药。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "停下来休息，试图从周围环境寻找提示。",
      "outcome": "玩家注意到附近的花丛中有一只小动物，它似乎受到某种伤害。玩家救治了它，并得到了一种可以解惑的特殊草药。",
      "result": "partial",
      "next": "retry"
    }
  ]
}
